import fs from "node:fs";

// ─────────────────────────────────────────────────────────────────────────────
// Correctifs NDC — à lancer dans StackBlitz :  node apply-fixes.mjs  puis commit.
//
// Contenu :
//   • Header : anti-débordement laptops + boutons Portail/Contact compacts.
//   • Header : ordre de la nav fixé — Notre réseau, Nos offres, Nos services,
//     Certifications, À propos de nous, Actualités. (La piste « menu éditable
//     dans WP » a été abandonnée : ce script la retire si elle était appliquée.)
//   • Services : libellé « Bénéfice client » → « Bénéfice ».
//   • Datacenters : statuts « Livré/En construction » → « Opérationnel/En cours ».
//   • Certifications : ancien statut « obtenu » normalisé en « conforme ».
//   • Hero : la légende sous-texte (heroCaptionSub) est lue depuis WP.
// ─────────────────────────────────────────────────────────────────────────────

const files = {
  "app/globals.css": "",
  "app/[locale]/page.tsx": "",
  "app/[locale]/layout.tsx": "",
  "components/SiteHeader.tsx": "",
  "lib/wordpress.ts": "",
  "components/MapClient.tsx": "",
  "components/Services.tsx": "",
  "messages/fr.json": "",
  "messages/en.json": "",
};

for (const [path, b64] of Object.entries(files)) {
  const dir = path.substring(0, path.lastIndexOf("/"));
  if (dir) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path, Buffer.from(b64, "base64").toString("utf8"));
  console.log("✓ écrit :", path);
}

console.log("\nCorrectifs appliqués. Pense à commit + push.");
